# t55-s3: Swarm 分诊系统
class Agent:
    def __init__(self, name: str, instructions: str, functions: dict = None):
        self.name = name
        self.instructions = instructions
        self.functions = functions or {}


class Swarm:
    def run(self, agent: Agent, user_msg: str, max_turns: int = 6) -> list:
        history = [{"speaker": "user", "text": user_msg}]
        current = agent
        for _ in range(max_turns):
            reply, next_agent = self._respond(current, history)
            history.append({"speaker": current.name, "text": reply})
            if next_agent is None:
                break
            print(f"  🔄 {current.name} 移交给 {next_agent.name}")
            current = next_agent
        return history

    def _respond(self, agent: Agent, history: list) -> tuple:
        msg = history[-1]["text"]
        if agent.name == "triage":
            if "退款" in msg or "退钱" in msg:
                return ("为您转接退款专员", refund_agent)
            if "报错" in msg or "闪退" in msg or "bug" in msg.lower():
                return ("为您转接技术支持", tech_agent)
            return ("请补充: 是退款/技术/账单哪类问题?", None)
        # 专家处理: 发现不属于自己的领域可以转回分诊台
        if agent.name == "tech" and "退款" in msg:
            return ("这其实退款问题, 我帮您转回分诊台", triage)
        return (f"已处理您的问题: '{msg[:15]}...' 解决方案已发送", None)


def transfer_to_refund():
    return refund_agent

def transfer_to_tech():
    return tech_agent

tech_agent = Agent("tech", "你是技术支持, 只处理bug/报错类问题", {})
refund_agent = Agent("refund", "你是退款专员, 只处理退款/退钱", {})
triage = Agent("triage",
               "你是分诊员: 意图明确立即移交, 绝不自己回答专业问题",
               {"transfer_to_refund": transfer_to_refund, "transfer_to_tech": transfer_to_tech})

if __name__ == "__main__":
    s = Swarm()
    for msg in ["我要退款", "APP一直报错闪退", "你好我有个问题"]:
        print(f"用户: {msg}")
        for h in s.run(triage, msg)[1:]:
            print(f"  [{h['speaker']}] {h['text']}")
        print()
